const body = $json.body ?? $json;

if (body.type !== 'material_form' || !body.submissionId || !body.company_name || !body.email) {
  throw new Error('Ogiltig material-payload');
}

const packageNames = { start: 'Start', foretag: 'Företag', pro: 'Pro' };
const clean = (value, max = 300) => String(value ?? '').replace(/[<>]/g, '').trim().slice(0, max);
const company = clean(body.company_name, 120);
const contact = clean(body.contact_name, 120);
const email = clean(body.email, 254);
const phone = clean(body.phone, 40);
const packageName = packageNames[body.package_id] ?? clean(body.package_id, 30) ?? 'Okänt';
const materialLink = clean(body.material_link, 1000);

const lines = [
  '📦 Nytt material till hemsida',
  '',
  `Företag: ${company}`,
  `Kontakt: ${contact}`,
  `E-post: ${email}`,
  phone ? `Telefon: ${phone}` : null,
  `Paket: ${packageName}`,
  `Submission ID: ${clean(body.submissionId, 100)}`,
  '',
  materialLink ? `Materialmapp: ${materialLink}` : 'Materialmapp: Ingen länk angiven',
  '',
  'Öppna kunden i adminpanelen:',
  'https://fertekz.com/admin'
].filter(Boolean);

return [{ json: { message: lines.join('\n'), submissionId: body.submissionId } }];
